$mtx = New-Object System.Threading.Mutex($false, $mname)
$owned = $false
try { $owned = $mtx.WaitOne(10000) } catch [System.Threading.AbandonedMutexException] { $owned = $true }
$written = $false
try {
    for ($i = 0; $i -lt 40 -and -not $written; $i++) {
